\begin{lem}\ollabel{wellordinitialsegment}
Let $\tuple{A, <}$ and $\tuple{B, \lessdot}$ be well-orderings. If $f
\colon A \to B$ is an isomorphism and $a \in A$, then
$\funrestrictionto{f}{A_{a}} : A_a \to B_{f(a)}$ is an isomorphism.
\end{lem}

